import{_ as a,o,c as l,a0 as n}from"./chunks/framework.D2qex3w9.js";const g=JSON.parse('{"title":"Use Cases — dynamic-column-config","description":"","frontmatter":{},"headers":[],"relativePath":"tests/use-cases/dynamic-column-config.md","filePath":"tests/use-cases/dynamic-column-config.md"}'),t={name:"tests/use-cases/dynamic-column-config.md"};function i(c,e,r,s,d,u){return o(),l("div",null,[...e[0]||(e[0]=[n('<h1 id="use-cases-—-dynamic-column-config" tabindex="-1">Use Cases — dynamic-column-config <a class="header-anchor" href="#use-cases-—-dynamic-column-config" aria-label="Permalink to &quot;Use Cases — dynamic-column-config&quot;">​</a></h1><blockquote><p>Generado a partir de <code>openspec/specs/dynamic-column-config/spec.md</code></p></blockquote><hr><h2 id="uc-col-visibility-01-columna-oculta-no-se-renderiza" tabindex="-1">UC-COL-VISIBILITY-01: Columna oculta no se renderiza <a class="header-anchor" href="#uc-col-visibility-01-columna-oculta-no-se-renderiza" aria-label="Permalink to &quot;UC-COL-VISIBILITY-01: Columna oculta no se renderiza&quot;">​</a></h2><p><strong>Requirement:</strong> REQ-COL-VISIBILITY — Column Visibility</p><p><strong>Dado</strong> una tabla con columnas <code>[{key: &#39;name&#39;, header: &#39;Name&#39;}, {key: &#39;secret&#39;, header: &#39;Secret&#39;, visible: false}]</code><strong>Cuando</strong> la tabla se renderiza <strong>Entonces</strong> solo la columna <code>name</code> aparece en el DOM renderizado <strong>Y</strong> la columna <code>secret</code> está ausente del DOM (no meramente oculta via CSS)</p><hr><h2 id="uc-col-visibility-02-columna-sin-visible-se-renderiza-normalmente" tabindex="-1">UC-COL-VISIBILITY-02: Columna sin visible se renderiza normalmente <a class="header-anchor" href="#uc-col-visibility-02-columna-sin-visible-se-renderiza-normalmente" aria-label="Permalink to &quot;UC-COL-VISIBILITY-02: Columna sin visible se renderiza normalmente&quot;">​</a></h2><p><strong>Requirement:</strong> REQ-COL-VISIBILITY — Column Visibility</p><p><strong>Dado</strong> una columna sin propiedad <code>visible</code><strong>Cuando</strong> la tabla se renderiza <strong>Entonces</strong> esa columna aparece en el DOM renderizado</p><hr><h2 id="uc-col-tooltip-01-tooltip-aparece-al-hacer-hover" tabindex="-1">UC-COL-TOOLTIP-01: Tooltip aparece al hacer hover <a class="header-anchor" href="#uc-col-tooltip-01-tooltip-aparece-al-hacer-hover" aria-label="Permalink to &quot;UC-COL-TOOLTIP-01: Tooltip aparece al hacer hover&quot;">​</a></h2><p><strong>Requirement:</strong> REQ-COL-TOOLTIP — Cell Tooltip</p><p><strong>Dado</strong> una columna <code>{key: &#39;email&#39;, header: &#39;Email&#39;, tooltip: &#39;Click to copy&#39;}</code><strong>Cuando</strong> el usuario hace hover sobre una celda de esa columna <strong>Entonces</strong> aparece un tooltip de Material con el texto &quot;Click to copy&quot;</p><hr><h2 id="uc-col-tooltip-02-columna-sin-tooltip-no-muestra-tooltip" tabindex="-1">UC-COL-TOOLTIP-02: Columna sin tooltip no muestra tooltip <a class="header-anchor" href="#uc-col-tooltip-02-columna-sin-tooltip-no-muestra-tooltip" aria-label="Permalink to &quot;UC-COL-TOOLTIP-02: Columna sin tooltip no muestra tooltip&quot;">​</a></h2><p><strong>Requirement:</strong> REQ-COL-TOOLTIP — Cell Tooltip</p><p><strong>Dado</strong> una columna sin propiedad <code>tooltip</code><strong>Cuando</strong> el usuario hace hover sobre una celda de esa columna <strong>Entonces</strong> no aparece ningún tooltip</p><hr><h2 id="uc-col-clickable-01-celda-clickeable-emite-cellclick-con-detaildata" tabindex="-1">UC-COL-CLICKABLE-01: Celda clickeable emite cellClick con detailData <a class="header-anchor" href="#uc-col-clickable-01-celda-clickeable-emite-cellclick-con-detaildata" aria-label="Permalink to &quot;UC-COL-CLICKABLE-01: Celda clickeable emite cellClick con detailData&quot;">​</a></h2><p><strong>Requirement:</strong> REQ-COL-CLICKABLE — Clickable Cells</p><p><strong>Dado</strong> una columna <code>{key: &#39;name&#39;, header: &#39;Name&#39;, clickeable: true}</code><strong>Y</strong> una columna de detalle <code>{key: &#39;id&#39;, header: &#39;ID&#39;, visible: false, detail: true}</code><strong>Y</strong> una fila <code>{name: &#39;Alice&#39;, id: &#39;42&#39;}</code><strong>Cuando</strong> el usuario hace clic en la celda &quot;Alice&quot; <strong>Entonces</strong> el payload de <code>cellClick</code> incluye <code>detailData: [{label: &#39;ID&#39;, value: &#39;42&#39;}]</code></p><hr><h2 id="uc-col-clickable-02-celda-no-clickeable-no-emite-evento" tabindex="-1">UC-COL-CLICKABLE-02: Celda no clickeable no emite evento <a class="header-anchor" href="#uc-col-clickable-02-celda-no-clickeable-no-emite-evento" aria-label="Permalink to &quot;UC-COL-CLICKABLE-02: Celda no clickeable no emite evento&quot;">​</a></h2><p><strong>Requirement:</strong> REQ-COL-CLICKABLE — Clickable Cells</p><p><strong>Dado</strong> una columna sin <code>clickeable</code> o con <code>clickeable: false</code><strong>Cuando</strong> el usuario hace clic en una celda de esa columna <strong>Entonces</strong> no se emite ningún evento <code>cellClick</code></p><hr><h2 id="uc-col-filterable-01-filtro-global-excluye-columna-con-filterable-false" tabindex="-1">UC-COL-FILTERABLE-01: Filtro global excluye columna con filterable: false <a class="header-anchor" href="#uc-col-filterable-01-filtro-global-excluye-columna-con-filterable-false" aria-label="Permalink to &quot;UC-COL-FILTERABLE-01: Filtro global excluye columna con filterable: false&quot;">​</a></h2><p><strong>Requirement:</strong> REQ-COL-FILTERABLE — Filterable Columns</p><p><strong>Dado</strong> columnas <code>[{key: &#39;name&#39;, header: &#39;Name&#39;}, {key: &#39;notes&#39;, header: &#39;Notes&#39;, filterable: false}]</code><strong>Y</strong> filas <code>[{name: &#39;Alice&#39;, notes: &#39;confidential&#39;}]</code><strong>Cuando</strong> el usuario escribe &quot;confidential&quot; en el filtro global <strong>Entonces</strong> no se muestran filas (la columna notes fue excluida de la búsqueda)</p><hr><h2 id="uc-col-filterable-02-filtro-global-incluye-columna-sin-filterable" tabindex="-1">UC-COL-FILTERABLE-02: Filtro global incluye columna sin filterable <a class="header-anchor" href="#uc-col-filterable-02-filtro-global-incluye-columna-sin-filterable" aria-label="Permalink to &quot;UC-COL-FILTERABLE-02: Filtro global incluye columna sin filterable&quot;">​</a></h2><p><strong>Requirement:</strong> REQ-COL-FILTERABLE — Filterable Columns</p><p><strong>Dado</strong> columnas sin propiedad <code>filterable</code><strong>Cuando</strong> el usuario escribe un término en el filtro global <strong>Entonces</strong> todas las columnas son buscadas (compatibilidad hacia atrás)</p><hr><h2 id="uc-backward-compat-01-configuracion-legacy-funciona-identicamente" tabindex="-1">UC-BACKWARD-COMPAT-01: Configuración legacy funciona idénticamente <a class="header-anchor" href="#uc-backward-compat-01-configuracion-legacy-funciona-identicamente" aria-label="Permalink to &quot;UC-BACKWARD-COMPAT-01: Configuración legacy funciona idénticamente&quot;">​</a></h2><p><strong>Requirement:</strong> REQ-BACKWARD-COMPAT — Backward Compatibility</p><p><strong>Dado</strong> un componente de tabla con un array legacy de columnas <code>[{key: &#39;name&#39;, header: &#39;Name&#39;}]</code><strong>Cuando</strong> el componente se inicializa <strong>Entonces</strong> todas las columnas se renderizan normalmente <strong>Y</strong> no aparecen tooltips al hacer hover sobre celdas <strong>Y</strong> hacer clic en celdas no tiene efecto <strong>Y</strong> el filtro global busca en todas las columnas</p><hr><h2 id="uc-detail-prop-01-columna-detail-preserva-dato-invisible-en-click" tabindex="-1">UC-DETAIL-PROP-01: Columna detail preserva dato invisible en click <a class="header-anchor" href="#uc-detail-prop-01-columna-detail-preserva-dato-invisible-en-click" aria-label="Permalink to &quot;UC-DETAIL-PROP-01: Columna detail preserva dato invisible en click&quot;">​</a></h2><p><strong>Requirement:</strong> REQ-DETAIL-PROP — Detail Property</p><p><strong>Dado</strong> una columna <code>{key: &#39;id&#39;, header: &#39;ID&#39;, visible: false, detail: true}</code><strong>Y</strong> una fila <code>{name: &#39;Alice&#39;, id: &#39;42&#39;}</code><strong>Cuando</strong> se hace clic en una celda clickeable de esa fila <strong>Entonces</strong> el payload <code>cellClick</code> incluye <code>{label: &#39;ID&#39;, value: &#39;42&#39;}</code> en <code>detailData</code></p><hr><h2 id="uc-detail-prop-02-columna-invisible-sin-detail-queda-excluida-de-emision" tabindex="-1">UC-DETAIL-PROP-02: Columna invisible sin detail queda excluida de emisión <a class="header-anchor" href="#uc-detail-prop-02-columna-invisible-sin-detail-queda-excluida-de-emision" aria-label="Permalink to &quot;UC-DETAIL-PROP-02: Columna invisible sin detail queda excluida de emisión&quot;">​</a></h2><p><strong>Requirement:</strong> REQ-DETAIL-PROP — Detail Property</p><p><strong>Dado</strong> una columna <code>{key: &#39;secret&#39;, header: &#39;Secret&#39;, visible: false}</code> sin <code>detail: true</code><strong>Cuando</strong> se hace clic en una celda clickeable de esa fila <strong>Entonces</strong> <code>secret</code> NO aparece en <code>detailData</code></p><hr><h2 id="uc-detail-emission-01-multiples-columnas-detail-emiten-todos-los-valores" tabindex="-1">UC-DETAIL-EMISSION-01: Múltiples columnas detail emiten todos los valores <a class="header-anchor" href="#uc-detail-emission-01-multiples-columnas-detail-emiten-todos-los-valores" aria-label="Permalink to &quot;UC-DETAIL-EMISSION-01: Múltiples columnas detail emiten todos los valores&quot;">​</a></h2><p><strong>Requirement:</strong> REQ-DETAIL-EMISSION — Detail Data Emission</p><p><strong>Dado</strong> columnas con <code>key: &#39;orderId&#39;, detail: true</code> y <code>key: &#39;market&#39;, detail: true</code><strong>Y</strong> una fila <code>{name: &#39;Alice&#39;, orderId: &#39;ORD-123&#39;, market: &#39;NYSE&#39;}</code><strong>Cuando</strong> el usuario hace clic en una celda clickeable de esa fila <strong>Entonces</strong> <code>detailData</code> contiene dos entradas con labels &quot;Order ID&quot; y &quot;Market&quot;</p><hr><h2 id="uc-detail-emission-02-sin-columnas-detail-emite-array-vacio" tabindex="-1">UC-DETAIL-EMISSION-02: Sin columnas detail emite array vacío <a class="header-anchor" href="#uc-detail-emission-02-sin-columnas-detail-emite-array-vacio" aria-label="Permalink to &quot;UC-DETAIL-EMISSION-02: Sin columnas detail emite array vacío&quot;">​</a></h2><p><strong>Requirement:</strong> REQ-DETAIL-EMISSION — Detail Data Emission</p><p><strong>Dado</strong> columnas sin ninguna con <code>detail: true</code><strong>Cuando</strong> se hace clic en una celda clickeable <strong>Entonces</strong> <code>cellClick.detailData</code> es <code>[]</code></p><hr><h2 id="uc-detail-format-01-detaildata-sigue-el-contrato-label-value" tabindex="-1">UC-DETAIL-FORMAT-01: detailData sigue el contrato label/value <a class="header-anchor" href="#uc-detail-format-01-detaildata-sigue-el-contrato-label-value" aria-label="Permalink to &quot;UC-DETAIL-FORMAT-01: detailData sigue el contrato label/value&quot;">​</a></h2><p><strong>Requirement:</strong> REQ-DETAIL-FORMAT — Detail Data Format</p><p><strong>Dado</strong> una columna <code>{key: &#39;code&#39;, header: &#39;Code&#39;, detail: true}</code><strong>Y</strong> una fila con <code>code: &#39;ABC&#39;</code><strong>Cuando</strong> se hace clic en una celda clickeable <strong>Entonces</strong> <code>detailData[0]</code> es igual a <code>{label: &#39;Code&#39;, value: &#39;ABC&#39;}</code></p>',58)])])}const p=a(t,[["render",i]]);export{g as __pageData,p as default};
